(()=>{'use strict';const TEAM_URL='ffws-br-2026-s2/teams.json?v=20260729-profile-lite-v1',PLAYER_URL='ffws-br-2026-s2/players.json?v=20260729-profile-lite-v1',STAGE_URL='ffws-br-2026-s2/stages.json?v=20260729-profile-lite-v1';const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toUpperCase(),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),num=v=>Number(v)||0;let cache=null;async function data(){if(cache)return cache;cache=Promise.all([fetch(TEAM_URL,{cache:'default'}).then(r=>r.json()),fetch(PLAYER_URL,{cache:'default'}).then(r=>r.json()),fetch(STAGE_URL,{cache:'default'}).then(r=>r.json())]).then(([teams,players,stages])=>({teams:teams.teams||[],players:players.players||[],entries:players.entries||[],stages}));return cache}function q(name){return new URLSearchParams(location.search).get(name)||''}function teamStats(name,stages){const out={points:0,kills:0,booyahs:0,matches:0,position:'—'};for(const key of ['classificatoria','segundaFase','final']){const stage=stages?.[key]||{};(stage.rows||[]).forEach(r=>{if(norm(r.team||r.equipe)===norm(name)){out.points+=num(r.points??r.pontos);out.kills+=num(r.kills??r.abates);out.booyahs+=num(r.booyahs??r.booyah);out.matches+=num(r.matches??r.quedas);out.position=r.position??r.posicao??out.position}});const blocks=key==='final'?(stage.days||[]):(stage.rounds||[]);blocks.forEach(b=>{const events=b.matches||b.rounds||[b];events.forEach(ev=>(ev.results||ev.rows||[]).forEach(r=>{if(norm(r.team||r.equipe)===norm(name)){out.points+=num(r.points??r.pontos);out.kills+=num(r.kills??r.abates);out.booyahs+=num(r.booyahs??r.booyah??(num(r.position||r.posicao)===1));out.matches+=num(r.matches||1)}}))})}return out}function playerStats(player,entries){const rows=entries.filter(e=>norm(e.name||e.player||e.jogador)===norm(player.name)&&norm(e.team||e.equipe)===norm(player.team));return rows.reduce((a,e)=>(a.kills+=num(e.kills??e.abates),a.damage+=num(e.damage??e.dano),a.assists+=num(e.assists??e.assistencias),a.matches+=num(e.matches??e.quedas??1),a),{kills:0,damage:0,assists:0,matches:0})}function badge(text){return`<span class="lite-badge">${esc(text)}</span>`}function setTitle(value){document.title=`${value} | Central Free Fire`}async function renderTeam(){const root=document.getElementById('profile-root'),name=q('time');try{const d=await data(),team=d.teams.find(t=>norm(t.name)===norm(name)||norm(t.abbreviation)===norm(name));if(!team)throw new Error('Equipe não encontrada');setTitle(team.name);const roster=d.players.filter(p=>norm(p.team)===norm(team.name)).sort((a,b)=>num(b.starter)-num(a.starter)||num(a.order)-num(b.order)),s=teamStats(team.name,d.stages);root.innerHTML=`<section class="lite-hero"><img src="${esc(team.logo||'escudo.webp')}" onerror="this.src='escudo.webp'" alt="${esc(team.name)}"><div><div class="lite-kicker">FFWS BRASIL 2026 SPLIT 2</div><h1>${esc(team.name)}</h1><div class="lite-sub">${esc(team.abbreviation)} • Brasil</div><div class="lite-badges">${badge(`${roster.length} jogadores`)}${badge('Temporada atual')}</div></div></section><div class="lite-grid">${[['Pontos',s.points],['Abates',s.kills],['Booyahs',s.booyahs],['Quedas',s.matches]].map(([l,v])=>`<div class="lite-stat"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><section class="lite-section"><h2>Elenco da temporada</h2><div class="lite-list">${roster.map(p=>`<a class="lite-row" href="jogador.html?jogador=${encodeURIComponent(p.name)}&time=${encodeURIComponent(p.team)}"><img src="silhueta.webp" alt=""><span><strong>${esc(p.name)}</strong><small>${esc(p.role||'Função não informada')} • ${esc(p.rosterStatus||'Elenco')}</small></span><span class="lite-right">${p.rookie?'ESTREANTE':p.captain?'CAPITÃO':'VER'}</span></a>`).join('')||'<div class="lite-empty">Elenco em breve.</div>'}</div></section>`}catch(e){root.innerHTML=`<div class="lite-error">${esc(e.message||'Não foi possível abrir esta equipe.')}</div>`}}async function renderPlayer(){const root=document.getElementById('profile-root'),name=q('jogador'),teamName=q('time');try{const d=await data(),candidates=d.players.filter(p=>norm(p.name)===norm(name)||norm(p.sourceName)===norm(name)||(p.aliases||[]).some(a=>norm(a)===norm(name))),player=candidates.find(p=>!teamName||norm(p.team)===norm(teamName))||candidates[0];if(!player)throw new Error('Jogador não encontrado');const team=d.teams.find(t=>norm(t.name)===norm(player.team)),s=playerStats(player,d.entries),avg=s.matches?(s.kills/s.matches).toFixed(2):'0.00';setTitle(player.name);root.innerHTML=`<section class="lite-hero"><img src="silhueta.webp" alt="${esc(player.name)}"><div><div class="lite-kicker">FFWS BRASIL 2026 SPLIT 2</div><h1>${esc(player.name)}</h1><div class="lite-sub">${esc(player.role||'Jogador')} • <a href="equipe.html?time=${encodeURIComponent(player.team)}" style="color:var(--accent);text-decoration:none">${esc(player.team)}</a></div><div class="lite-badges">${player.captain?badge('Capitão'):''}${player.rookie?badge('Estreante'):''}${player.starter?badge('Titular'):badge('Reserva')}</div></div></section><div class="lite-grid">${[['Abates',s.kills],['Quedas',s.matches],['Média K/Q',avg],['Assistências',s.assists]].map(([l,v])=>`<div class="lite-stat"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><section class="lite-section"><h2>Informações</h2><div class="lite-list"><a class="lite-row" href="equipe.html?time=${encodeURIComponent(player.team)}"><img src="${esc(team?.logo||'escudo.webp')}" onerror="this.src='escudo.webp'" alt=""><span><strong>${esc(player.team)}</strong><small>${esc(player.rosterStatus||'Elenco')} • ${esc(player.country?.toUpperCase()||'BR')}</small></span><span class="lite-right">VER EQUIPE</span></a></div></section>`}catch(e){root.innerHTML=`<div class="lite-error">${esc(e.message||'Não foi possível abrir este jogador.')}</div>`}}const mode=document.body.dataset.profileType;mode==='team'?renderTeam():renderPlayer()})();
